import Foundation
import MRCarveKit

// These tests hold whether or not the engine (hatch, raster, path ordering) is implemented:
// they rely on shape outlines generated by the model and only make conditional claims about engine output.
enum ModelJobCompilerTests {
    static func square(_ x: Double, _ y: Double, size: Double = 10, pen: Int = 0) -> DesignObject {
        DesignObject.rectangle(Rect2(minX: x, minY: y, maxX: x + size, maxY: y + size), penID: pen)
    }

    static func register() {
        test("compiler: consecutive same-pen objects merge into one item") {
            let project = Project(objects: [square(-20, -20), square(0, 0), square(10, 10)])
            let job = JobCompiler.compile(project)
            expectEqual(job.items.count, 1)
            expectEqual(job.items.first?.polylines.count, 3)
            expectEqual(job.items.first?.pen.id, 0)
        }

        test("compiler: pen changes keep mark order") {
            let project = Project(objects: [square(-20, -20, pen: 1), square(0, 0, pen: 2), square(10, 10, pen: 1)])
            let job = JobCompiler.compile(project)
            expectEqual(job.items.map(\.pen.id), [1, 2, 1])
            expectEqual(job.items.map(\.polylines.count), [1, 1, 1])
        }

        test("compiler: disabled pens, hidden objects and selection are skipped") {
            var project = Project(objects: [square(-20, -20, pen: 1), square(0, 0, pen: 2), square(10, 10, pen: 3)])
            project.updatePen(2) { $0.isEnabled = false }
            project.objects[2].isVisible = false
            expectEqual(JobCompiler.compile(project).items.map(\.pen.id), [1])

            project.objects[2].isVisible = true
            let only = JobCompiler.compile(project, options: .init(selection: [project.objects[2].id]))
            expectEqual(only.items.map(\.pen.id), [3])
            expect(JobCompiler.compile(project, options: .init(selection: [])).isEmpty)
        }

        test("compiler: pen parameters travel with the items") {
            var project = Project(objects: [square(0, 0, pen: 4)], repeatCount: 2)
            project.updatePen(4) { $0.markSpeed = 321; $0.loopCount = 3 }
            let job = JobCompiler.compile(project)
            expectEqual(job.repeatCount, 2)
            expectEqual(job.items.first?.pen.markSpeed, 321)
            expectEqual(job.items.first?.pen.loopCount, 3)
        }

        test("compiler: outline versus fill ordering") {
            var object = square(-5, -5)
            var fill = FillSettings()
            fill.layers[0].penID = 5
            fill.layers[0].spacing = 0.5
            fill.outlineFirst = true
            object.fill = fill
            var project = Project(objects: [object])

            // Outline first: pen 0 outline, then (if the engine hatches) pen 5.
            var job = JobCompiler.compile(project)
            expectEqual(job.items.first?.pen.id, 0)
            expectEqual(job.items.first?.polylines.count, 1)
            expect(job.items.count <= 2)
            if job.items.count == 2 { expectEqual(job.items[1].pen.id, 5) }

            // Hatch first: pen 5 (if any) precedes the outline, which is always last.
            project.objects[0].fill?.outlineFirst = false
            job = JobCompiler.compile(project)
            expectEqual(job.items.last?.pen.id, 0)
            if job.items.count == 2 { expectEqual(job.items[0].pen.id, 5) }

            // No outline: only hatch items (possibly none with a stub engine).
            project.objects[0].fill?.markOutline = false
            job = JobCompiler.compile(project)
            expect(job.items.allSatisfy { $0.pen.id == 5 })

            // Disabled hatch layer + outline: outline only.
            project.objects[0].fill?.markOutline = true
            project.objects[0].fill?.layers[0].isEnabled = false
            expectEqual(JobCompiler.compile(project).items.map(\.pen.id), [0])
        }

        test("compiler: fill on a line is ignored and images never mark their frame") {
            var line = DesignObject.line(from: Vec2(0, 0), to: Vec2(10, 0))
            line.fill = FillSettings()
            let img = DesignObject.image(try ImageContent(imageData: ModelProjectTests.tinyPNG()), longestSide: 10, penID: 1)
            let job = JobCompiler.compile(Project(objects: [line, img]))
            expectEqual(job.items.first?.pen.id, 0)
            expectEqual(job.items.first?.polylines.count, 1)
            expect(job.items.dropFirst().allSatisfy { $0.pen.id == 1 })
            expectClose(job.items.first?.polylines.first?.length ?? 0, 10)
            // Raster scan lines may be produced by the engine, but never the 10 × 5 frame rectangle.
            for item in job.items { for p in item.polylines { expect(!(p.isClosed && abs(p.length - 30) < 1e-6)) } }
        }

        test("compiler: framing job uses outlines and image frames") {
            let img = DesignObject.image(try ImageContent(imageData: ModelProjectTests.tinyPNG()), longestSide: 10)
            var hidden = square(20, 20)
            hidden.isVisible = false
            let project = Project(objects: [square(0, 0), img, hidden])
            let frame = JobCompiler.framingJob(project)
            expectEqual(frame.items.count, 1)
            expectEqual(frame.items[0].polylines.count, 2)
            expectEqual(frame.bounds, Rect2(minX: -5, minY: -2.5, maxX: 10, maxY: 10))
            expect(JobCompiler.framingJob(Project()).isEmpty)
        }

        test("compiler: field check") {
            let field = MachineProfile().field
            let inside = Project(objects: [square(-35, -35, size: 70)])
            expect(JobCompiler.fieldViolation(JobCompiler.compile(inside), field: field) == nil)
            expect(JobCompiler.objectsOutsideField(inside, field: field).isEmpty)
            let outside = Project(objects: [square(30, 0, size: 10), square(0, 0)])
            expect(JobCompiler.fieldViolation(JobCompiler.compile(outside), field: field) != nil)
            expectEqual(JobCompiler.objectsOutsideField(outside, field: field), [outside.objects[0].id])
        }

        test("compiler: time estimate") {
            var project = Project(objects: [square(0, 0)])
            project.updatePen(0) {
                $0.markSpeed = 100; $0.jumpSpeed = 1000; $0.loopCount = 2
                $0.laserOnDelay = 0; $0.laserOffDelay = 0; $0.endMarkDelay = 0; $0.cornerDelay = 0
                $0.minJumpDelay = 0; $0.maxJumpDelay = 0
            }
            let job = JobCompiler.compile(project)
            let e = JobCompiler.estimate(job)
            expectClose(e.markLength, 80)                       // 40 mm perimeter × 2 loops
            expectClose(job.markLength, 80)
            expect(e.duration >= 0.8 && e.duration < 0.9)       // 0.8 s marking + short jump
            expectEqual(JobCompiler.estimate(MarkJob(items: [])).duration, 0)

            project.repeatCount = 3
            expectClose(JobCompiler.estimate(JobCompiler.compile(project)).markLength, 240)
        }
    }
}
